const input = $input.first().json;
let services = [];
let currentPeriod = '';
let previousPeriod = '';

if (input.ResultsByTime) {
  // AWS Cost Explorer format
  const results = input.ResultsByTime;
  const latest = results[results.length - 1];
  currentPeriod = `${latest.TimePeriod.Start} / ${latest.TimePeriod.End}`;
  services = (latest.Groups || []).map(g => ({
    name: g.Keys[0],
    current: parseFloat(g.Metrics.UnblendedCost.Amount),
    previous: 0,
    currency: g.Metrics.UnblendedCost.Unit
  }));
} else {
  // CSV fixture: raw text
  const csvText = typeof input === 'string' ? input : (input.data || JSON.stringify(input));
  const allLines = String(csvText).split('\n');
  const byService = {};
  const periods = [];

  for (const line of allLines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('ServiceName')) continue;
    const parts = trimmed.split(',');
    if (parts.length < 3) continue;
    const [svc, period, amt] = parts;
    if (!periods.includes(period)) periods.push(period);
    if (!byService[svc]) byService[svc] = {};
    byService[svc][period] = parseFloat(amt) || 0;
  }

  const sorted = periods.sort();
  currentPeriod = sorted[sorted.length - 1] || 'Apr 2025';
  previousPeriod = sorted[sorted.length - 2] || 'Mar 2025';
  services = Object.entries(byService).map(([name, p]) => ({
    name,
    current: p[currentPeriod] || 0,
    previous: p[previousPeriod] || 0,
    currency: 'USD'
  }));
}

const totalCurrent = services.reduce((s, r) => s + r.current, 0);
const totalPrevious = services.reduce((s, r) => s + r.previous, 0);
const deltaPercent = totalPrevious > 0 ? ((totalCurrent - totalPrevious) / totalPrevious * 100).toFixed(1) : 'N/A';
const topServices = [...services].sort((a, b) => b.current - a.current).slice(0, 5);
const threshold = parseFloat($env.COST_ALERT_THRESHOLD || '2000');

return [{
  json: {
    summary: { currentPeriod, previousPeriod, totalCurrent: totalCurrent.toFixed(2), totalPrevious: totalPrevious.toFixed(2), deltaPercent, currency: 'USD' },
    topServices,
    allServices: services,
    alertThreshold: threshold,
    isOverThreshold: totalCurrent > threshold
  }
}];

